using System.Data;
using System.Globalization;
using System.IO;
using System.Windows;
using System.Windows.Controls;
using Microsoft.Win32;
namespace SchoolApp;
public class ServiceWindow:Window
{
 readonly int id;readonly TextBox title,cost,duration,description,discount;string main="";readonly List<string> photos=new();readonly Image preview=new(){Height=130};readonly ListBox gallery=new(){Height=160};
 public ServiceWindow(int serviceId){id=serviceId;Ui.Setup(this,id==0?"Добавление услуги":"Редактирование услуги");Width=690;Height=820;MinHeight=600;var p=new StackPanel{Margin=new Thickness(16)};Content=new ScrollViewer{Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};p.Children.Add(Ui.Header(id==0?"Новая услуга":"Редактирование услуги"));DataRow? r=id==0?null:Db.Query("SELECT * FROM Service WHERE ID=@id",("@id",id)).Rows[0];if(id!=0){var key=Ui.Field(p,"Идентификатор",id.ToString());key.IsReadOnly=true;}title=Ui.Field(p,"Название",r?["Title"].ToString()??"");cost=Ui.Field(p,"Стоимость, ₽",r?["Cost"].ToString()??"0");duration=Ui.Field(p,"Длительность, минут (0–240)",r==null?"60":(Convert.ToDecimal(r["DurationInSeconds"])/60).ToString());description=Ui.Field(p,"Описание",r?["Description"].ToString()??"");description.AcceptsReturn=true;description.MinHeight=60;description.TextWrapping=TextWrapping.Wrap;discount=Ui.Field(p,"Скидка, % (0–100)",r==null||r["Discount"]==DBNull.Value?"0":(Convert.ToDecimal(r["Discount"])*100).ToString());main=r?["MainImagePath"].ToString()??"";preview.Source=Ui.Picture(main);p.Children.Add(preview);p.Children.Add(Ui.Button("Выбрать главное изображение",()=>{var files=Choose(false);if(files.Length>0){main=Copy(files[0]);preview.Source=Ui.Picture(main);}}));p.Children.Add(new TextBlock{Text="Дополнительные изображения"});p.Children.Add(gallery);if(id!=0)foreach(DataRow photo in Db.Query("SELECT PhotoPath FROM ServicePhoto WHERE ServiceID=@id",("@id",id)).Rows)photos.Add(photo[0].ToString()!);RefreshPhotos();var bar=new WrapPanel();p.Children.Add(bar);bar.Children.Add(Ui.Button("Добавить фотографии",()=>{foreach(var f in Choose(true))photos.Add(Copy(f));RefreshPhotos();}));bar.Children.Add(Ui.Button("Убрать выбранную",()=>{int i=gallery.SelectedIndex;if(i>=0){photos.RemoveAt(i);RefreshPhotos();}}));bar.Children.Add(Ui.Button("Сохранить",Save));bar.Children.Add(Ui.Button("Отмена",Close));}
 static string[] Choose(bool multi){var d=new OpenFileDialog{Filter="Изображения|*.jpg;*.jpeg;*.png;*.bmp",Multiselect=multi};return d.ShowDialog()==true?d.FileNames:[];}
 static string Copy(string path){if(Ui.Picture(path)==null)throw new Exception("Не удалось прочитать изображение.");var relative="Assets/Uploads/"+Guid.NewGuid().ToString("N")+Path.GetExtension(path);var full=Path.Combine(AppContext.BaseDirectory,relative);Directory.CreateDirectory(Path.GetDirectoryName(full)!);File.Copy(path,full);return relative;}
 void RefreshPhotos(){gallery.Items.Clear();foreach(var photo in photos){var p=new StackPanel{Orientation=Orientation.Horizontal};p.Children.Add(new Image{Source=Ui.Picture(photo),Width=100,Height=75});p.Children.Add(new TextBlock{Text=Path.GetFileName(photo),Margin=new Thickness(12),VerticalAlignment=VerticalAlignment.Center});gallery.Items.Add(p);}}
 static decimal Number(string s){if(decimal.TryParse(s,NumberStyles.Number,CultureInfo.CurrentCulture,out var n)||decimal.TryParse(s.Replace(',','.'),NumberStyles.Number,CultureInfo.InvariantCulture,out n))return n;throw new Exception("Введите корректное число.");}
 void Save(){string name=title.Text.Trim();if(name.Length==0||name.Length>100)throw new Exception("Название должно содержать от 1 до 100 символов.");decimal c=Number(cost.Text),m=Number(duration.Text),d=Number(discount.Text);if(c<0||c>922337203685477.5807m)throw new Exception("Недопустимая стоимость.");if(m<0||m>240||m*60!=decimal.Truncate(m*60))throw new Exception("Длительность: от 0 до 240 минут с точностью до секунды.");if(d<0||d>100)throw new Exception("Скидка: от 0 до 100 процентов.");if(Db.Query("SELECT ID FROM Service WHERE Title=@title AND ID<>@id",("@title",name),("@id",id)).Rows.Count>0)throw new Exception("Услуга с таким названием уже существует.");Db.Save(id,name,c,(int)(m*60),description.Text.Trim(),d/100,main,photos);DialogResult=true;}
}
